/*
 * Exhaust every rank-four F_101 span generated by the nominated anchor
 * and three of the other 53 directions.  Input: n m, then n rows of
 * m integer entries followed by one nonnegative weight per row.
 * Output: total triples, independent triples, maximum contained weight.
 * The source uses only C99 integer arithmetic, not floating point.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define N 54
#define D 20
#define P 101

static int rows[N][D], weight[N], inverse[P];
static int reduce(int a) { a%=P; return a<0 ? a+P : a; }
struct span { int b[4][D], pivot[4], count; };

static int insert(struct span *s, int index) {
    int x[D],i,j,t,p=-1;
    memcpy(x,rows[index],sizeof x);
    for (i=0;i<s->count;i++) {
        t=x[s->pivot[i]];
        if (t) for(j=s->pivot[i];j<D;j++)
            x[j]=reduce(x[j]-t*s->b[i][j]);
    }
    for(i=0;i<D;i++) if(x[i]) {p=i;break;}
    if(p<0) return 0;
    t=inverse[x[p]];
    for(j=p;j<D;j++) s->b[s->count][j]=reduce(t*x[j]);
    s->pivot[s->count]=p;
    s->count++;
    return 1;
}
static int contains(const struct span *s,int index) {
    int x[D],i,j,t;
    memcpy(x,rows[index],sizeof x);
    for(i=0;i<s->count;i++) {
        t=x[s->pivot[i]];
        if(t) for(j=s->pivot[i];j<D;j++)
            x[j]=reduce(x[j]-t*s->b[i][j]);
    }
    for(i=0;i<D;i++) if(x[i]) return 0;
    return 1;
}
int main(int argc,char **argv) {
    int n,m,anchor,i,j,k,a,b,c,total=0,independent=0,best=-1;
    if(argc!=2 || sscanf(argv[1],"%d",&anchor)!=1 ||
       anchor<0 || anchor>=N) return 2;
    if(scanf("%d %d",&n,&m)!=2 || n!=N || m!=D) return 3;
    for(i=0;i<N;i++) {
        for(j=0;j<D;j++) {
            if(scanf("%d",&rows[i][j])!=1) return 4;
            rows[i][j]=reduce(rows[i][j]);
        }
        if(scanf("%d",&weight[i])!=1 || weight[i]<0) return 5;
    }
    for(i=1;i<P;i++) for(j=1;j<P;j++)
        if((i*j)%P==1) {inverse[i]=j;break;}
    for(a=0;a<N;a++) for(b=a+1;b<N;b++) for(c=b+1;c<N;c++) {
        struct span s;
        int sum=0;
        if(a==anchor || b==anchor || c==anchor) continue;
        total++;
        memset(&s,0,sizeof s);
        if(!insert(&s,anchor) || !insert(&s,a) ||
           !insert(&s,b) || !insert(&s,c)) continue;
        independent++;
        for(k=0;k<N;k++) if(contains(&s,k)) sum+=weight[k];
        if(sum>best) best=sum;
    }
    printf("%d %d %d\n",total,independent,best);
    return 0;
}
